87:     version: false,  //Adds -v,--version => gets version by parsing a nearby package.json
88:     status: false,   //Adds -k,--no-color & --debug => display plain status messages /display debug messages
89:     timeout: false,  //Adds -t,--timeout N => timeout the process after N seconds
90:     catchall: false, //Adds -c,--catch => catch and output uncaughtExceptions
