128:  * @param {Array|String} argv
129:  * @param {Boolean} keep_arg0 (optional - default is false)
130:  * @api public
131:  */
132: cli.setArgv = function (arr, keep_arg0) {
133:     if (typeof arr == 'string') {
134:       arr = arr.split(' ');
135:     } else {
136:       arr = arr.slice();
