143:     if (!keep_arg0 && (['node', 'node.exe'].indexOf(cli.native.path.basename(cli.app)) !== -1
144:             || cli.native.path.basename(process.execPath) === cli.app
145:             || process.execPath === cli.app)) {
146:         cli.app = arr.shift();
