157: /**
158:  * Returns the next opt, or false if no opts are found.
159:  *
160:  * @return {String} opt
161:  * @api public
162:  */
163: cli.next = function () {
164:     if (!argv_parsed) {
165:         cli.args = [];
166:         argv_parsed = true;
167:     }
168: 
169:     curr_val = null;
170: 
171:     //If we're currently in a group of short opts (e.g. -abc), return the next opt
172:     if (short_tags.length) {
173:         curr_opt = short_tags.shift();
174:         full_opt = '-' + curr_opt;
175:         return curr_opt;
176:     }
177: 
178:     if (!argv.length) {
179:         return false;
180:     }
181: 
182:     curr_opt = argv.shift();
183: 
184:     //If an escape sequence is found (- or --), subsequent opts are ignored
185:     if (curr_opt === '-' || curr_opt === '--') {
186:         while (argv.length) {
187:             cli.args.push(argv.shift());
188:         }
189:         return false;
190:     }
191: 
192:     //If the next element in argv isn't an opt, add it to the list of args
193:     if (curr_opt[0] !== '-') {
194:         cli.args.push(curr_opt);
195:         return cli.next();
196:     } else {
197:         //Check if the opt is short/long
198:         is_long = curr_opt[1] === '-';
199:         curr_opt = curr_opt.substr(is_long ? 2 : 1);
200:     }
201: 
202:     //Accept grouped short opts, e.g. -abc => -a -b -c
203:     if (!is_long && curr_opt.length > 1) {
204:         short_tags = curr_opt.split('');
205:         return cli.next();
206:     }
207: 
208:     var eq, len;
209: 
210:     //Check if the long opt is in the form --option=VALUE
211:     if (is_long && (eq = curr_opt.indexOf('=')) >= 0) {
212:         curr_val = curr_opt.substr(eq + 1);
213:         curr_opt = curr_opt.substr(0, eq);
214:         len = curr_val.length;
215:         //Allow values to be quoted
216:         if ((curr_val[0] === '"' && curr_val[len - 1] === '"') ||
217:             (curr_val[0] === "'" && curr_val[len - 1] === "'"))
218:         {
219:             curr_val = curr_val.substr(1, len-2);
220:         }
221:         if (curr_val.match(/^[0-9]+$/)) {
222:             curr_val = parseInt(curr_val, 10);
223:         }
224:     }
225: 
226:     //Save the opt representation for later
227:     full_opt = (is_long ? '--' : '-') + curr_opt;
228: 
229:     return curr_opt;
230: };
