232: /**
233:  * Parses command line opts.
234:  *
235:  * `opts` must be an object with opts defined like:
236:  *        long_tag: [short_tag, description, value_type, default_value];
237:  *
238:  * `commands` is an optional array or object for apps that are of the form
239:  *      my_app [OPTIONS] <command> [ARGS]
240:  *  The command list is output with usage information + there is bundled
241:  *  support for auto-completion, etc.
242:  *
243:  * See README.md for more information.
244:  *
245:  * @param {Object} opts
246:  * @param {Object} commands (optional)
247:  * @return {Object} opts (parsed)
248:  * @api public
249:  */
250: cli.parse = function (opts, command_def) {
251:     var default_val, i, o, parsed = cli.options, seen,
252:         catch_all = !opts;
253:     opt_list = opts || {};
254:     commands = command_def;
255:     command_list = commands || [];
256:     if (commands && !Array.isArray(commands)) {
257:         command_list = Object.keys(commands);
258:     }
259:     while ((o = cli.next())) {
260:         seen = false;
261:         for (var opt in opt_list) {
262:             if (!(opt_list[opt] instanceof Array)) {
263:                 continue;
264:             }
265:             if (!opt_list[opt][0]) {
266:                 opt_list[opt][0] = opt;
267:             }
268:             if (o === opt || o === opt_list[opt][0]) {
269:                 seen = true;
270:                 if (opt_list[opt].length === 2) {
271:                     parsed[opt] = true;
272:                     break;
273:                 }
274:                 default_val = null;
275:                 if (opt_list[opt].length === 4) {
276:                     default_val = opt_list[opt][3];
277:                 }
278:                 if (opt_list[opt][2] instanceof Array) {
279:                     for (i = 0, l = opt_list[opt][2].length; i < l; i++) {
280:                         if (typeof opt_list[opt][2][i] === 'number') {
281:                             opt_list[opt][2][i] += '';
282:                         }
283:                     }
284:                     parsed[opt] = cli.getArrayValue(opt_list[opt][2], is_long ? null : default_val);
285:                     break;
286:                 }
287:                 if (opt_list[opt][2].toLowerCase) {
288:                     opt_list[opt][2] = opt_list[opt][2].toLowerCase();
289:                 }
290:                 switch (opt_list[opt][2]) {
291:                 case 'string': case 1: case true:
292:                     parsed[opt] = cli.getValue(default_val);
293:                     break;
294:                 case 'int': case 'number': case 'num':
295:                 case 'time': case 'seconds': case 'secs': case 'minutes': case 'mins':
296:                 case 'x': case 'n':
297:                     parsed[opt] = cli.getInt(default_val);
298:                     break;
299:                 case 'date': case 'datetime': case 'date_time':
300:                     parsed[opt] = cli.getDate(default_val);
301:                     break;
302:                 case 'float': case 'decimal':
303:                     parsed[opt] = cli.getFloat(default_val);
304:                     break;
305:                 case 'path': case 'file': case 'directory': case 'dir':
306:                     parsed[opt] = cli.getPath(default_val, opt_list[opt][2]);
307:                     break;
308:                 case 'email':
309:                     parsed[opt] = cli.getEmail(default_val);
310:                     break;
311:                 case 'url': case 'uri': case 'domain': case 'host':
312:                     parsed[opt] = cli.getUrl(default_val, opt_list[opt][2]);
313:                     break;
314:                 case 'ip':
315:                     parsed[opt] = cli.getIp(default_val);
316:                     break;
317:                 case 'bool': case 'boolean': case 'on':
318:                     parsed[opt] = true;
319:                     break;
320:                 case 'false': case 'off': case false: case 0:
321:                     parsed[opt] = false;
322:                     break;
323:                 default:
324:                      cli.fatal('Unknown opt type "' + opt_list[opt][2] + '"');
325:                 }
326:                 break;
327:             }
328:         }
329:         if (!seen) {
330:             if (enable.help && (o === 'h' || o === 'help')) {
331:                 cli.getUsage();
332:             } else if (enable.version && (o === 'v' || o === 'version')) {
333:                 if (cli.version == null) {
334:                     cli.parsePackageJson();
335:                 }
336:                 console.error(cli.app + ' v' + cli.version);
337:                 cli.exit();
338:                 break;
339:             } else if (enable.catchall && (o === 'c' || o === 'catch')) {
340:                 continue;
341:             } else if (enable.status && (o === 'k' || o === 'no-color')) {
342:                 cli.no_color = (o === 'k' || o === 'no-color');
343:                 continue;
344:             } else if (enable.status && (o === 'debug')) {
345:                 show_debug = o === 'debug';
346:                 continue;
347:             } else if (enable.timeout && (o === 't' || o === 'timeout')) {
348:                 var secs = cli.getInt();
349:                 setTimeout(function () {
350:                     cli.fatal('Process timed out after ' + secs + 's');
351:                 }, secs * 1000);
352:                 continue;
353:             } else if (catch_all) {
354:                 parsed[o] = curr_val || true;
355:                 continue;
356:             }
357:             cli.fatal('Unknown option ' + full_opt);
358:         }
359:     }
360:     //Fill the remaining options with their default value or null
361:     for (var opt in opt_list) {
362:         default_val = opt_list[opt].length === 4 ? opt_list[opt][3] : null;
363:         if (!(opt_list[opt] instanceof Array)) {
364:             parsed[opt] = opt_list[opt];
365:             continue;
366:         } else if (typeof parsed[opt] === 'undefined') {
367:             parsed[opt] = default_val;
368:         }
369:     }
370:     if (command_list.length) {
371:         if (cli.args.length === 0) {
372:             if (enable.help) {
373:                 cli.getUsage();
374:             } else {
375:                 cli.fatal('A command is required (' + command_list.join(', ') + ').');
376:             }
377:             return cli.exit(1);
378:         } else {
379:             cli.command = cli.autocompleteCommand(cli.args.shift());
380:         }
381:     }
382:     cli.argc = cli.args.length;
383:     return parsed;
384: };
