386: /**
387:  * Helper method for matching a command from the command list.
388:  *
389:  * @param {String} command
390:  * @return {String} full_command
391:  * @api public
392:  */
393: cli.autocompleteCommand = function (command) {
394:     var list;
395:     if (!(command_list instanceof Array)) {
396:         list = Object.keys(command_list);
397:     } else {
398:         list = command_list;
399:     }
400:     var i, j = 0, c = command.length, tmp_list;
401:     if (list.length === 0 || list.indexOf(command) !== -1) {
402:         return command;
403:     }
404:     for (i = 0; i < c; i++) {
405:         tmp_list = [];
406:         l = list.length;
407:         if (l <= 1) break;
408:         for (j = 0; j < l; j++)
409:             if (list[j].length >= i && list[j][i] === command[i])
410:                 tmp_list.push(list[j]);
411:         list = tmp_list;
412:     }
413:     l = list.length;
414:     if (l === 1) {
415:         return list[0];
416:     } else if (l === 0) {
417:         cli.fatal('Unknown command "' + command + '"' + (enable.help ? '. Please see --help for more information' : ''));
418:     } else {
419:         list.sort();
420:         cli.fatal('The command "' + command + '" is ambiguous and could mean "' + list.join('", "') + '"');
421:     }
422: };
