424: /**
425:  * Adds methods to output styled status messages to stderr.
426:  *
427:  * Added methods are cli.info(msg), cli.error(msg), cli.ok(msg), and
428:  * cli.debug(msg).
429:  *
430:  * To control status messages, use the 'status' plugin
431:  *    1) debug() messages are hidden by default. Display them with
432:  *       the --debug opt.
433:  *    2) to hide all status messages, use the -s or --silent opt.
434:  *
435:  * @api private
436:  */
437: cli.status = function (msg, type) {
438:     var pre;
439:     switch (type) {
440:     case 'info':
441:         pre = cli.no_color ? 'INFO:' : '\x1B[33mINFO\x1B[0m:';
442:         break;
443:     case 'debug':
444:         pre = cli.no_color ? 'DEBUG:' : '\x1B[36mDEBUG\x1B[0m:';
445:         break;
446:     case 'error':
447:     case 'fatal':
448:         pre = cli.no_color ? 'ERROR:' : '\x1B[31mERROR\x1B[0m:';
449:         break;
450:     case 'ok':
451:         pre = cli.no_color ? 'OK:' : '\x1B[32mOK\x1B[0m:';
452:         break;
453:     }
454:     msg = pre + ' ' + msg;
455:     if (type === 'fatal') {
456:         console.error(msg);
457:         return cli.exit(1);
458:     }
459:     if (enable.status && !show_debug && type === 'debug') {
460:         return;
461:     }
462:     console.error(msg);
463: };
464: ['info','error','ok','debug','fatal'].forEach(function (type) {
465:     cli[type] = function (msg) {
466:         cli.status(msg, type);
467:     };
468: });
