470: /**
471:  * Sets the app name and version.
472:  *
473:  * Usage:
474:  *     setApp('myapp', '0.1.0');
475:  *     setApp('./package.json'); //Pull name/version from package.json
476:  *
477:  * @param {String} name
478:  * @return cli (for chaining)
479:  * @api public
480:  */
481: cli.setApp = function (name, version) {
482:     if (name.indexOf('package.json') !== -1) {
483:         cli.parsePackageJson(name);
484:     } else {
485:         cli.app = name;
486:         cli.version = version;
487:     }
