491: /**
492:  * Parses the version number from package.json. If no path is specified, cli
493:  * will attempt to locate a package.json in ./, ../ or ../../
494:  *
495:  * @param {String} path (optional)
496:  * @api public
497:  */
498: cli.parsePackageJson = function (path) {
499:     var parse_packagejson = function (path) {
500:         var packagejson = JSON.parse(cli.native.fs.readFileSync(path, 'utf8'));
