971:     var defaultStackErrorHandler = function (req, res, err) {
972:         if (err) {
973:             console.error(err.stack);
974:             res.writeHead(500, {"Content-Type": "text/plain"});
975:             return res.end(err.stack + "\n");
976:         }
977:         res.writeHead(404, {"Content-Type": "text/plain"});
978:         res.end("Not Found\n");
