1039:     stream = stream || process.stdout;
1040:     if (progress < 0 || progress > 1 || isNaN(progress)) return;
1041:     if (!decimals) decimals = 0;
1042:     var now = (new Date()).getTime();
1043:     if (last_progress_call && (now - last_progress_call) < 100 && progress !== 1) {
1044:         return; //Throttle progress calls
1045:     }
1046:     last_progress_call = now;
1047: 
1048:     var pwr = Math.pow(10, decimals);
1049:     var percentage_as_num = Math.floor(progress * 100 * pwr) / pwr;
1050:     if (!stream.isTTY && percentage_as_num < 100 && percentage_as_num - last_progress_percentage < min_progress_increase) {
1051:         return; //don't over-print if not TTY
1052:     }
1053:     last_progress_percentage = percentage_as_num;
1054:     var percentage = percentage_as_num + '%';
1055:     for (var i = 0; i < decimals; i++) {
1056:         percentage += ' ';
1057:     }
1058:     if (!stream.isTTY) {
1059:         if (percentage_as_num < 100) {
1060:             stream.write(percentage + '...');
1061:         }
1062:         else {
1063:             stream.write(percentage + '\n');
1064:             last_progress_percentage = 0;
1065:         }
1066:         return;
1067:     }
