1069:         str       = '';
1070:     if (bar_length == 0 && progress > 0) {
1071:         bar_length = 1;
1072:     }
1073:     for (i = 1; i <= progress_len; i++) {
1074:         str += i <= bar_length ? '#' : ' ';
1075:     }
